package com.friendoncampus.order.service;
import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.*;import tools.jackson.databind.json.JsonMapper;
public class OrderEvidenceExportService {
 private final JdbcClient db;private final JsonMapper json=JsonMapper.builder().build();public OrderEvidenceExportService(JdbcClient db){this.db=db;}
 @Transactional(readOnly=true) public Export read(UUID orderId,String cursor,int limit){if(limit<1||limit>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Limit must be between 1 and 100");long committed=db.sql("SELECT lifecycle_sequence FROM orders WHERE id=:id").param("id",orderId).query(Long.class).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found"));int offset=0;long pinned=committed;if(cursor!=null){try{String[]p=new String(Base64.getUrlDecoder().decode(cursor),StandardCharsets.UTF_8).split(":");pinned=Long.parseLong(p[0]);offset=Integer.parseInt(p[1]);}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid cursor");}}
  List<JsonNode> events=db.sql("SELECT payload::text FROM outbox_events WHERE aggregate_id=:id AND topic='order.lifecycle.events' AND (payload->'data'->>'sourceSequence')::bigint<=:pinned ORDER BY (payload->'data'->>'sourceSequence')::bigint").param("id",orderId).param("pinned",pinned).query(String.class).list().stream().map(json::readTree).toList();if(events.size()!=pinned)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"A trustworthy Order evidence baseline is unavailable");List<Map<String,Object>> records=new ArrayList<>();for(JsonNode e:events){JsonNode d=e.path("data");Map<String,Object> data=new LinkedHashMap<>(json.convertValue(d,Map.class));data.put("kind","ORDER");Map<String,Object> r=new LinkedHashMap<>();r.put("eventId",UUID.fromString(e.path("eventId").asText()));r.put("source","order-service");r.put("stream","order.lifecycle.events");r.put("sourceSequence",d.path("sourceSequence").asLong());r.put("orderId",orderId);r.put("action",d.path("action").asText());String actor=e.path("actor").path("userId").asText(null);r.put("actorUserId",actor==null?null:UUID.fromString(actor));r.put("occurredAt",e.path("occurredAt").asText());r.put("ingestedAt",e.path("occurredAt").asText());r.put("data",data);records.add(r);}int end=Math.min(offset+limit,records.size());String next=end<records.size()?Base64.getUrlEncoder().withoutPadding().encodeToString((pinned+":"+end).getBytes(StandardCharsets.UTF_8)):null;return new Export(orderId,"order-"+orderId+"-"+pinned,new Checkpoint("order-service","order.lifecycle.events",orderId,pinned,Instant.now()),records.subList(offset,end),next);}
 public record Checkpoint(String source,String stream,UUID aggregateId,long committedSequence,Instant checkedAt){} public record Export(UUID orderId,String snapshotId,Checkpoint checkpoint,List<Map<String,Object>> records,String nextCursor){}
}
